package io.knowledgebrain.notification;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.planning.delivery.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_NOTIFICATION_DATABASE_URL",matches=".+")
class NotificationStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;NotificationStore store;String schema;UUID space,actor;
 PGSimpleDataSource owner(){var d=new PGSimpleDataSource();d.setURL(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_URL"));d.setUser("brain_notification");d.setPassword(System.getenv("BRAIN_TEST_NOTIFICATION_DATABASE_PASSWORD"));return d;}
 @BeforeEach void init(){ds=owner();schema="notification_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new NotificationStore(ds,Clock.systemUTC());space=DispatchFixtures.ids.next();actor=DispatchFixtures.ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 NotificationStore.Notification create(){assertTrue(store.accept(DispatchFixtures.event(space,DispatchFixtures.ids.next())));return store.list(space,"ACTIVE","ALL",null,100).items().stream().max(Comparator.comparing(NotificationStore.Notification::deliveredAt)).orElseThrow();}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 @Test void duplicatesAndRecoveryReplayNeverOverwriteReadStateOrPinnedProvenance()throws Exception{var bytes=DispatchFixtures.event(space,DispatchFixtures.ids.next());assertTrue(store.accept(bytes));var v=store.list(space,"ACTIVE","ALL",null,20).items().getFirst();var read=store.change(space,v.notificationId(),actor,1,true,false,"b".repeat(32));assertFalse(store.accept(bytes));assertEquals(read,store.get(space,v.notificationId()));var changed=ReminderDeliveryEnvelopeV1.parseFrom(bytes).toBuilder().setTraceId("c".repeat(32)).build().toByteArray();assertThrows(IllegalArgumentException.class,()->store.accept(changed));assertEquals(1,count("notification_inbox"));assertEquals(2,count("notification_revision"));assertEquals(v.source(),read.source());assertEquals(1,count("notification"));}
 @Test void readsRetirementAndHistoryKeepIndependentCanonicalVersions(){var v=create();for(int n=1;n<=6;n++){v=store.change(space,v.notificationId(),actor,n,n%2==1,false,"b".repeat(32));}var id=v.notificationId();assertEquals(7,v.version());assertEquals(v,store.change(space,id,actor,7,false,false,"b".repeat(32)));assertEquals(7,count("notification_revision"));status(412,()->store.change(space,id,actor,1,true,false,"b".repeat(32)));status(404,()->store.get(actor,id));assertEquals(List.of(7L,6L,5L,4L,3L),store.history(space,id,Long.MAX_VALUE,5).stream().map(NotificationStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,id,3,5).stream().map(NotificationStore.Revision::version).toList());var retired=store.change(space,id,actor,7,null,true,"b".repeat(32));assertEquals(retired,store.change(space,id,actor,8,null,true,"b".repeat(32)));assertEquals("RETIRED",store.get(space,id).state());assertEquals(8,count("notification_revision"));assertEquals(actor,store.history(space,id,Long.MAX_VALUE,1).getFirst().actorId());}
 @Test void controlledOutboxFailureRollsBackInboxDeliveryAndReadMutation(){sql.execute("CREATE FUNCTION fail_notification() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled notification failure'; END $$");sql.execute("CREATE TRIGGER fail_notification BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_notification()");var bytes=DispatchFixtures.event(space,DispatchFixtures.ids.next());assertThrows(RuntimeException.class,()->store.accept(bytes));assertEquals(0,count("notification_inbox"));assertEquals(0,count("notification"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_notification");assertTrue(store.accept(bytes));var v=store.list(space,"ACTIVE","ALL",null,20).items().getFirst();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_notification");assertThrows(RuntimeException.class,()->store.change(space,v.notificationId(),actor,1,true,false,"b".repeat(32)));assertEquals(v,store.get(space,v.notificationId()));assertEquals(1,count("notification_revision"));}
 @Test void filteredPagesAndConcurrentDuplicateDeliveryRemainTenantBound()throws Exception{var bytes=DispatchFixtures.event(space,DispatchFixtures.ids.next());try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return store.accept(bytes);});var b=pool.submit(()->{gate.await();return store.accept(bytes);});assertNotEquals(a.get(),b.get());}for(int n=0;n<22;n++)create();var a=store.list(space,"ACTIVE","UNREAD",null,20);var b=store.list(space,"ACTIVE","UNREAD",a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,b.items().size());assertNull(b.nextAfter());status(400,()->store.list(space,"RETIRED","UNREAD",a.nextAfter(),20));status(400,()->store.list(space,"ACTIVE","ALL",a.nextAfter(),20));status(400,()->store.list(actor,"ACTIVE","UNREAD",a.nextAfter(),20));assertEquals(23,count("notification"));}
 @Test void ownCanonicalSchemaMigratesWithoutOtherOwnerAccess(){var owner=owner();Flyway.configure().dataSource(owner).locations("classpath:db/migration").load().migrate();var jdbc=new JdbcTemplate(owner);assertEquals("brain_notification",jdbc.queryForObject("SELECT current_database()",String.class));assertThrows(RuntimeException.class,()->jdbc.queryForObject("SELECT 1 FROM goal",Integer.class));assertFalse(store.seeded());store.seededNow();assertTrue(store.seeded());}
}
